import numpy as np
from packages.utils import *
import matplotlib.pyplot as plt


f_res = 0.025
f_min = 0.8
f_max = 1.8

wgw_res = 0.05
wgw_min = 1
wgw_max = 2

x_freqs = compute_freqs(f_min, f_max, f_res)
y_wg_widths_factor = compute_freqs(wgw_min, wgw_max, wgw_res)
y_wg_widths = y_wg_widths_factor/(2*3.47)


def matrix_with_mask(matrix, matrix_mask, tolerance=0):
    mask = (matrix_mask <= tolerance)
    return np.where(mask, matrix, 0)


def find_max(matrix, n_th_max = 1):
    flat = matrix.ravel()

    idx = np.argpartition(flat, -n_th_max)[-n_th_max]
    max_pos = np.unravel_index(idx, matrix.shape)

    wgw = wgw_min + max_pos[0]*wgw_res
    freq = f_min+max_pos[1]*f_res
    eff = matrix[max_pos]

    return max_pos, freq, wgw, eff


